    "The address must be http://… or https://… with a host, without a blank, a user name or a fragment.": {de: "Die Adresse muss http://… oder https://… mit einem Host sein, ohne Leerzeichen, Benutzernamen oder Fragment.", en: "The address must be http://… or https://… with a host, without a blank, a user name or a fragment."},
    "A placeholder cannot stand in the address' host.": {de: "Im Host der Adresse kann kein Platzhalter stehen.", en: "A placeholder cannot stand in the address' host."},
    "A webhook has at most {n} headers.": {de: "Ein Webhook hat höchstens {n} Kopfzeilen.", en: "A webhook has at most {n} headers."},
    "\"{name}\" is not a header's name.": {de: "„{name}“ ist kein Name einer Kopfzeile.", en: "\"{name}\" is not a header's name."},
    "A header needs a name.": {de: "Eine Kopfzeile braucht einen Namen.", en: "A header needs a name."},
    "The header {name} is set by the request itself.": {de: "Die Kopfzeile {name} setzt der Aufruf selbst.", en: "The header {name} is set by the request itself."},
    "The header {name} is there twice.": {de: "Die Kopfzeile {name} steht zweimal da.", en: "The header {name} is there twice."},
    "The value of the header {name} is too long or has a line break.": {de: "Der Wert der Kopfzeile {name} ist zu lang oder hat einen Zeilenumbruch.", en: "The value of the header {name} is too long or has a line break."},
    "The body is longer than {n} bytes.": {de: "Der Inhalt ist länger als {n} Bytes.", en: "The body is longer than {n} bytes."},
    "There is no secret {name}: enter it in the settings first.": {de: "Es gibt kein Geheimnis {name}: erst in den Einstellungen eintragen.", en: "There is no secret {name}: enter it in the settings first."},
    "Enter the hardware address: AA:BB:CC:DD:EE:FF.": {de: "Die Hardware-Adresse eingeben: AA:BB:CC:DD:EE:FF.", en: "Enter the hardware address: AA:BB:CC:DD:EE:FF."},
    "The broadcast address is an IPv4 address like 192.168.1.255, or empty.": {de: "Die Broadcast-Adresse ist eine IPv4-Adresse wie 192.168.1.255 oder leer.", en: "The broadcast address is an IPv4 address like 192.168.1.255, or empty."},
    "Method": {de: "Methode", en: "Method"},
